@@ -0,0 +1,18 @@
+import type { Rollup } from "./types.js";
+
+export class MetricsStore {
+  private readonly rollupsByMetric = new Map<string, Rollup[]>();
+
+  append(rollup: Rollup): void {
+    const list = this.rollupsByMetric.get(rollup.metric);
+    if (list) {
+      list.push(rollup);
+    } else {
+      this.rollupsByMetric.set(rollup.metric, [rollup]);
+    }
+  }
+
+  read(metric: string): readonly Rollup[] {
+    return this.rollupsByMetric.get(metric) ?? [];
+  }
+}
